            <img src="@Model.ImageUrl" alt="" class="w-full h-full object-cover" />
        </div>
    }
    <div class="relative z-10 px-8 py-16 md:py-24 md:px-12">
        <h1 class="text-4xl md:text-5xl font-extrabold mb-4">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Text))
        {
            <p class="text-lg md:text-xl text-indigo-100 max-w-3xl">@Model.Text</p>
        }
    </div>
</div>

