@using Umbraco.Extensions
@using Umbraco.Bench.Umbraco.Models
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlogFrontPage>
@{
    Layout = "~/Views/_Layout.cshtml";
}

@await Html.GetBlockGridHtmlAsync(Model, "blocks")

@{
    var posts = Model.Children<BlogPost>();
}
@if (posts is { Count: > 0 })
{
    <section class="mt-12">
        <h2 class="text-2xl font-bold text-gray-900 mb-6">Latest Posts</h2>
        <div class="grid gap-8 md:grid-cols-2">
            @foreach (var post in posts)
            {
                <a href="@post.Url()" class="block bg-white rounded-xl shadow-sm border border-gray-200 hover:shadow-md transition-shadow p-6">
                    <h3 class="text-xl font-semibold text-gray-900 mb-2">@post.PageTitle</h3>
                </a>
            }
        </div>
    </section>
}

